        return listOf(UMethod::class.java)
    }

    override fun createUastHandler(context: JavaContext): UElementHandler {
        return object : UElementHandler() {
            override fun visitMethod(node: UMethod) {
                if (node.isConstructor) return
                val evaluator = context.evaluator
                val annotation = evaluator.findAnnotation(node, "ReturnThis")
                if (annotation == null) return

                // Check if method returns this
                if (!returnsThis(node)) {
                    context.report(
                        ISSUE,
                        node,
                        context.getNameLocation(node),
                        "Method must return `this`"
                    )
                }
            }
        }
    }

    private fun returnsThis(method: UMethod): Boolean {
        val body = method.uastBody ?: return true // abstract or native, skip or assume ok? Let's skip abstract.
        if (method.hasModifierProperty("abstract")) return true

        var found = false
        body.accept(object : UastVisitor {
            override fun visitReturnExpression(node: UReturnExpression): Boolean {
                if (node.returnExpression is UThisExpression) {
                    found = true
                }
                return super.visitReturnExpression(node)
            }
        })
        return found
    }

    companion object {
        val ISSUE = Issue.create(
            id = "ReturnThis",
            briefDescription = "Method must return `this`",
            explanation = "Methods annotated with `@ReturnThis` (usually in the super method that this method is overriding) should also `return this`.",
            category = Category.CORRECTNESS,
            priority = 5,
            severity = Severity.ERROR,
            implementation = Implementation(ReturnThisDetector::class.java, Scope.JAVA_FILE_SCOPE)
        )
    }
}
```

